input.schema:
{
  "type": "record",
  "name": "Envelope",
  "namespace": "axt",
  "doc": "One AXT message. Defined in spec/envelope.md. The field order is part of the format: format is always the first field, signature always the last.",
  "fields": [
    {
      "name": "format",
      "type": "int",
      "doc": "Version of the envelope format. 1 for the envelope defined in spec/envelope.md. Every later envelope schema keeps this field first and of type int."
    },
    {
      "name": "kind",
      "type": {
        "type": "enum",
        "name": "Kind",
        "doc": "What the message is. Each kind is defined in the document named in spec/envelope.md.",
        "symbols": [
          "MANIFEST",
          "OFFER",
          "ACCEPT",
          "DECLINE",
          "DATA",
          "DELETE",
          "ACK",
          "ERROR",
          "KEY_MOVE"
        ]
      },
      "doc": "What the message is, and so which schema its body has."
    },
    {
      "name": "sender",
      "type": {
        "type": "fixed",
        "name": "PublicKey",
        "size": 32,
        "doc": "An Ed25519 public key in the encoding of RFC 8032. Defined in spec/keys.md."
      },
      "doc": "The Ed25519 public key of the sending installation, which made the signature."
    },
    {
      "name": "record",
      "type": [
        "null",
        {
          "type": "record",
          "name": "RecordRef",
          "doc": "Which record, and which version of it, a message is about. Defined in spec/records.md.",
          "fields": [
            {
              "name": "id",
              "type": {
                "type": "string",
                "logicalType": "uuid"
              },
              "doc": "The record's stable id, a UUID in its 36-character lower-case text form."
            },
            {
              "name": "version",
              "type": "long",
              "doc": "The record's version. Defined in spec/records.md."
            }
          ]
        }
      ],
      "default": null,
      "doc": "The record the message is about; null for messages that are not about one record."
    },
    {
      "name": "body",
      "type": "bytes",
      "doc": "Empty, or one datum in Avro single-object encoding: the marker C3 01, the 8-byte little-endian CRC-64-AVRO fingerprint of the datum's writer schema, then the datum in Avro binary encoding."
    },
    {
      "name": "signature",
      "type": {
        "type": "fixed",
        "name": "Signature",
        "size": 64,
        "doc": "An Ed25519 signature. Defined in spec/keys.md."
      },
      "doc": "The sender's signature over the message. What it covers is defined in spec/keys.md."
    }
  ]
}

{
  "type": "record",
  "name": "Manifest",
  "namespace": "axt",
  "doc": "The types an app takes and what it does with them; the body of a MANIFEST message. Defined in spec/manifest.md. Its schema changes only with a new envelope format.",
  "fields": [
    {
      "name": "revision",
      "type": "long",
      "doc": "The revision of this manifest, at least 1. It rises with every change of the manifest's content, so that a receiver can tell the latest of several manifests of the same app apart from older ones."
    },
    {
      "name": "app_name",
      "type": "string",
      "doc": "The name the app gives itself, as plain text on one line, such as Old Brain Fix. It is shown to the other app's user; it does not identify the app, the sender key of the envelope does."
    },
    {
      "name": "app_url",
      "type": [
        "null",
        "string"
      ],
      "default": null,
      "doc": "An absolute https URL of a page about the app. Null when the app names none."
    },
    {
      "name": "formats",
      "type": {
        "type": "array",
        "items": "int"
      },
      "doc": "The envelope formats the app reads, each at least 1, without duplicates. It includes the format of the envelope that carries this manifest."
    },
    {
      "name": "takes",
      "type": {
        "type": "array",
        "items": {
          "type": "record",
          "name": "ManifestTake",
          "doc": "One type the app takes, the versions of it it takes, and what it does with its records.",
          "fields": [
            {
              "name": "type",
              "type": "string",
              "doc": "The full name of the type, namespace and name, such as axt.example.v1.Appointment. Matched exactly; the major version is part of the name."
            },
            {
              "name": "min_version",
              "type": "int",
              "doc": "The lowest version of the type the app takes, as the type's axt.version attribute numbers it; at least 1. A schema without a valid axt.version counts as version 1."
            },
            {
              "name": "max_version",
              "type": [
                "null",
                "int"
              ],
              "default": null,
              "doc": "The highest version of the type the app takes, at least min_version. Null when the app takes every version from min_version on."
            },
            {
              "name": "purpose",
              "type": "string",
              "doc": "One sentence in English, plain text on one line, on what the app does with records of the type, such as: An Appointment becomes a Reminder."
            },
            {
              "name": "purpose_translations",
              "type": {
                "type": "map",
                "values": "string"
              },
              "default": {},
              "doc": "The sentence of the field purpose in other languages. Each key is a BCP 47 language tag other than en, such as de or pt-BR; each value is the sentence in that language, plain text on one line. Empty when there are none."
            }
          ]
        }
      },
      "default": [],
      "doc": "The types the app takes, each full name at most once. Empty when the app takes no type by name."
    },
    {
      "name": "any_type",
      "type": [
        "null",
        {
          "type": "record",
          "name": "ManifestAnyType",
          "doc": "That the app takes every type that takes does not name, in every version, and what it does with their records.",
          "fields": [
            {
              "name": "purpose",
              "type": "string",
              "doc": "One sentence in English, plain text on one line, on what the app does with records of a type that takes does not name, such as: Any other type becomes a searchable Note."
            },
            {
              "name": "purpose_translations",
              "type": {
                "type": "map",
                "values": "string"
              },
              "default": {},
              "doc": "The sentence of the field purpose in other languages, keyed by BCP 47 language tag other than en, as in ManifestTake. Empty when there are none."
            }
          ]
        }
      ],
      "default": null,
      "doc": "Whether the app takes every type that takes does not name. Null when it takes only the types in takes."
    },
    {
      "name": "sends",
      "type": [
        "null",
        {
          "type": "array",
          "items": {
            "type": "record",
            "name": "ManifestSend",
            "doc": "One type the app may send, and the versions of it it writes.",
            "fields": [
              {
                "name": "type",
                "type": "string",
                "doc": "The full name of the type, namespace and name, such as axt.example.v1.Pet."
              },
              {
                "name": "min_version",
                "type": "int",
                "doc": "The lowest version of the type the app writes, as the type's axt.version attribute numbers it; at least 1. A schema without a valid axt.version counts as version 1."
              },
              {
                "name": "max_version",
                "type": [
                  "null",
                  "int"
                ],
                "default": null,
                "doc": "The highest version of the type the app writes, at least min_version. Null when the app does not say."
              }
            ]
          }
        }
      ],
      "default": null,
      "doc": "The types the app may send, each full name at most once; for display only. Null when the app does not say; empty when it sends no type."
    },
    {
      "name": "encryption_key",
      "type": [
        "null",
        {
          "type": "fixed",
          "name": "ManifestEncryptionKey",
          "size": 32,
          "doc": "An X25519 public key in the encoding of RFC 7748. Defined in spec/keys.md."
        }
      ],
      "default": null,
      "doc": "The X25519 public key of this installation with which other apps encrypt messages to it through a relay, as spec/keys.md defines. Null when the app takes no messages through a relay."
    },
    {
      "name": "relay",
      "type": [
        "null",
        {
          "type": "record",
          "name": "ManifestRelay",
          "doc": "The relay and the mailbox at it into which other apps put messages for this installation. Defined in spec/transports.md.",
          "fields": [
            {
              "name": "url",
              "type": "string",
              "doc": "The base URL of the relay: an absolute https URL with a host, ending with a slash, without user information, query or fragment, at most 256 bytes, such as https://relay.example.org/axt/. The paths of the relay's interface are appended to it."
            },
            {
              "name": "mailbox",
              "type": {
                "type": "fixed",
                "name": "ManifestRelayMailbox",
                "size": 32,
                "doc": "A mailbox id: the SHA-256 of a fixed prefix and the mailbox secret that only the mailbox's owner holds. Defined in spec/transports.md."
              },
              "doc": "The id of the mailbox at the relay into which other apps put messages for this installation."
            }
          ]
        }
      ],
      "default": null,
      "doc": "Where other apps put messages for this installation through a relay. Null when the app takes no messages through a relay; it is present exactly when encryption_key is."
    }
  ]
}

{
  "type": "record",
  "name": "KeyMove",
  "namespace": "axt",
  "doc": "The body of a KEY_MOVE message: the sender's key moves to a new installation. Defined in spec/keys.md. The message is signed with the old key, which is its sender.",
  "fields": [
    {
      "name": "new_sender",
      "type": {
        "type": "fixed",
        "name": "KeyMoveSigningKey",
        "size": 32,
        "doc": "An Ed25519 public key in the encoding of RFC 8032. Defined in spec/keys.md."
      },
      "doc": "The Ed25519 public key of the new installation, which signs every later message of the sender."
    },
    {
      "name": "new_encryption_key",
      "type": [
        "null",
        {
          "type": "fixed",
          "name": "KeyMoveEncryptionKey",
          "size": 32,
          "doc": "An X25519 public key in the encoding of RFC 7748. Defined in spec/keys.md."
        }
      ],
      "default": null,
      "doc": "The X25519 public key with which other apps encrypt messages to the new installation through a relay. Null when the new installation takes no messages through a relay."
    },
    {
      "name": "proof",
      "type": {
        "type": "fixed",
        "name": "KeyMoveProof",
        "size": 64,
        "doc": "An Ed25519 signature. Defined in spec/keys.md."
      },
      "doc": "The signature of the new key over the old key and the new key, as spec/keys.md defines; it shows that the new installation holds the new key."
    }
  ]
}

{
  "type": "record",
  "name": "Offer",
  "namespace": "axt",
  "doc": "The body of an OFFER message: the types, each with its writer schema, whose records the sender wants to send to one receiver. Defined in spec/protocol.md. Its schema changes only with a new envelope format.",
  "fields": [
    {
      "name": "to",
      "type": {
        "type": "fixed",
        "name": "OfferTo",
        "size": 32,
        "doc": "An Ed25519 public key in the encoding of RFC 8032. Defined in spec/keys.md."
      },
      "doc": "The Ed25519 public key of the app the offer is made to. An app ignores an offer that names another key."
    },
    {
      "name": "offer_id",
      "type": {
        "type": "string",
        "logicalType": "uuid"
      },
      "doc": "The id of the offer, a version 4 or 7 UUID in its 36-character lower-case text form, which the sender never uses for another offer. The answers to the offer name it."
    },
    {
      "name": "types",
      "type": {
        "type": "array",
        "items": {
          "type": "record",
          "name": "OfferType",
          "doc": "One type the sender offers, with the writer schema of its records.",
          "fields": [
            {
              "name": "schema",
              "type": "string",
              "doc": "The writer schema of the type as its full JSON text, doc attributes and axt.version included, with which the sender writes the records it sends under this offer. The type's full name and version are those of this schema."
            },
            {
              "name": "count",
              "type": "long",
              "default": 0,
              "doc": "The number of record messages of the type, DATA and DELETE together, that the sender is about to send under this offer; for display only. 0 when the sender does not say."
            }
          ]
        }
      },
      "doc": "The types offered, 1 to 256, each full name and each fingerprint at most once."
    }
  ]
}

{
  "type": "record",
  "name": "Accept",
  "namespace": "axt",
  "doc": "The body of an ACCEPT message: the types of one offer that the receiver takes. Defined in spec/protocol.md. Its schema changes only with a new envelope format.",
  "fields": [
    {
      "name": "to",
      "type": {
        "type": "fixed",
        "name": "AcceptTo",
        "size": 32,
        "doc": "An Ed25519 public key in the encoding of RFC 8032. Defined in spec/keys.md."
      },
      "doc": "The Ed25519 public key of the app that made the offer. An app ignores an answer that names another key."
    },
    {
      "name": "offer_id",
      "type": {
        "type": "string",
        "logicalType": "uuid"
      },
      "doc": "The id of the offer this message answers."
    },
    {
      "name": "types",
      "type": {
        "type": "array",
        "items": "string"
      },
      "doc": "The full names of the offered types the receiver takes, 1 to 256, each a type of the offer and each at most once."
    }
  ]
}

{
  "type": "record",
  "name": "Decline",
  "namespace": "axt",
  "doc": "The body of a DECLINE message: the types of one offer that the receiver does not take, each with the reason. Defined in spec/protocol.md. Its schema changes only with a new envelope format.",
  "fields": [
    {
      "name": "to",
      "type": {
        "type": "fixed",
        "name": "DeclineTo",
        "size": 32,
        "doc": "An Ed25519 public key in the encoding of RFC 8032. Defined in spec/keys.md."
      },
      "doc": "The Ed25519 public key of the app that made the offer. An app ignores an answer that names another key."
    },
    {
      "name": "offer_id",
      "type": {
        "type": "string",
        "logicalType": "uuid"
      },
      "doc": "The id of the offer this message answers."
    },
    {
      "name": "types",
      "type": {
        "type": "array",
        "items": {
          "type": "record",
          "name": "DeclineType",
          "doc": "One offered type the receiver does not take.",
          "fields": [
            {
              "name": "type",
              "type": "string",
              "doc": "The full name of the offered type."
            },
            {
              "name": "reason",
              "type": {
                "type": "enum",
                "name": "DeclineReason",
                "doc": "Why the receiver does not take a type. NOT_WANTED: the receiver or its user chose not to take it. DOES_NOT_FIT: the type, in the offered version, does not fit the receiver's current manifest. DOES_NOT_RESOLVE: the offered schema does not resolve against the receiver's reader schema of the type. The default is for schema resolution only; within one envelope format every symbol is known.",
                "symbols": [
                  "NOT_WANTED",
                  "DOES_NOT_FIT",
                  "DOES_NOT_RESOLVE"
                ],
                "default": "NOT_WANTED"
              },
              "doc": "Why the receiver does not take the type."
            }
          ]
        }
      },
      "doc": "The offered types the receiver does not take, 1 to 256, each a type of the offer and each at most once."
    }
  ]
}

{
  "type": "record",
  "name": "Ack",
  "namespace": "axt",
  "doc": "The body of an ACK message: what the receiver did with record messages of the app it sends the acknowledgement to, and the key moves of that app it applied. Defined in spec/protocol.md. Its schema changes only with a new envelope format.",
  "fields": [
    {
      "name": "to",
      "type": {
        "type": "fixed",
        "name": "AckTo",
        "size": 32,
        "doc": "An Ed25519 public key in the encoding of RFC 8032. Defined in spec/keys.md."
      },
      "doc": "The Ed25519 public key of the app whose record messages are acknowledged, its current key as the receiver knows it. An app ignores an acknowledgement that names another key."
    },
    {
      "name": "records",
      "type": {
        "type": "array",
        "items": {
          "type": "record",
          "name": "AckRecord",
          "doc": "The outcome of one record message, as spec/records.md, section 7, defines it.",
          "fields": [
            {
              "name": "id",
              "type": {
                "type": "string",
                "logicalType": "uuid"
              },
              "doc": "The id of the record, as the acknowledged message carried it in its record field."
            },
            {
              "name": "version",
              "type": "long",
              "doc": "The version of the acknowledged message."
            },
            {
              "name": "outcome",
              "type": {
                "type": "enum",
                "name": "AckOutcome",
                "doc": "What the receiver did with the message, as spec/records.md, section 7, defines. APPLIED: took the record or deleted it as the message says. MERGED: took it except fields its user had changed. KEPT: took nothing, because its user's change covers the whole record. DUPLICATE: already had this version. STALE: already had a higher version. The default is for schema resolution only; within one envelope format every symbol is known.",
                "symbols": [
                  "APPLIED",
                  "MERGED",
                  "KEPT",
                  "DUPLICATE",
                  "STALE"
                ],
                "default": "DUPLICATE"
              },
              "doc": "What the receiver did with the message."
            },
            {
              "name": "receiver_version",
              "type": "long",
              "doc": "The receiver's version of the record after the message: equal to version, except for STALE, where it is higher."
            },
            {
              "name": "kept_fields",
              "type": {
                "type": "array",
                "items": "string"
              },
              "default": [],
              "doc": "For MERGED, the names of the fields whose values the receiver kept and that differ from the values in the message, as the writer schema of the message names them, each at most once. Empty for every other outcome."
            }
          ]
        }
      },
      "default": [],
      "doc": "The outcomes of record messages, 0 to 4096, each id and version at most once. Empty only when moved_from is not null."
    },
    {
      "name": "moved_from",
      "type": [
        "null",
        {
          "type": "fixed",
          "name": "AckMovedFrom",
          "size": 32,
          "doc": "An Ed25519 public key in the encoding of RFC 8032. Defined in spec/keys.md."
        }
      ],
      "default": null,
      "doc": "The key the receiver knew the app by before it applied the app's key move to the key in to, as spec/protocol.md defines. Null when the message acknowledges no key move."
    }
  ]
}

{
  "type": "record",
  "name": "Error",
  "namespace": "axt",
  "doc": "The body of an ERROR message: a message the receiver could not process, and why. Defined in spec/protocol.md. Its schema changes only with a new envelope format.",
  "fields": [
    {
      "name": "to",
      "type": {
        "type": "fixed",
        "name": "ErrorTo",
        "size": 32,
        "doc": "An Ed25519 public key in the encoding of RFC 8032. Defined in spec/keys.md."
      },
      "doc": "The Ed25519 public key of the app that sent the reported message. An app ignores an error that names another key."
    },
    {
      "name": "code",
      "type": {
        "type": "enum",
        "name": "ErrorCode",
        "doc": "Why the receiver could not process the message; spec/protocol.md defines each code. INVALID_MESSAGE: not a valid message of its kind. FORMAT_UNSUPPORTED: an envelope format the receiver does not read. TOO_LARGE: above a size limit of spec/envelope.md. SIGNATURE_INVALID: the signature does not verify. MANIFEST_INVALID: an invalid manifest. OFFER_INVALID: an invalid offer. RECORD_ID_INVALID: an invalid record id. VERSION_INVALID: a version below 1. SCHEMA_UNKNOWN: a body fingerprint the receiver has no schema for. NOT_ACCEPTED: a record message without an accepted offer of its type. TYPE_CHANGED: a record under another type than before. UNDECODABLE: a record body that cannot be decoded. KEY_MOVE_REJECTED: a key move the receiver did not apply. VALUE_INVALID: a record that decodes but holds a value that breaks a rule of its type, named in field. The default is for schema resolution only; within one envelope format every symbol is known.",
        "symbols": [
          "INVALID_MESSAGE",
          "FORMAT_UNSUPPORTED",
          "TOO_LARGE",
          "SIGNATURE_INVALID",
          "MANIFEST_INVALID",
          "OFFER_INVALID",
          "RECORD_ID_INVALID",
          "VERSION_INVALID",
          "SCHEMA_UNKNOWN",
          "NOT_ACCEPTED",
          "TYPE_CHANGED",
          "UNDECODABLE",
          "KEY_MOVE_REJECTED",
          "VALUE_INVALID"
        ],
        "default": "INVALID_MESSAGE"
      },
      "doc": "Why the receiver could not process the message."
    },
    {
      "name": "message_hash",
      "type": {
        "type": "fixed",
        "name": "ErrorMessageHash",
        "size": 32,
        "doc": "A SHA-256 hash."
      },
      "doc": "The SHA-256 of the reported message as the receiver got it, from its single-object marker to its last byte; through a relay, after opening and removing the padding."
    },
    {
      "name": "record",
      "type": [
        "null",
        {
          "type": "record",
          "name": "ErrorRecord",
          "doc": "The record field of the reported message.",
          "fields": [
            {
              "name": "id",
              "type": "string",
              "doc": "The id as the reported message carried it, which may not be a valid UUID."
            },
            {
              "name": "version",
              "type": "long",
              "doc": "The version as the reported message carried it, which may be below 1."
            }
          ]
        }
      ],
      "default": null,
      "doc": "The record field of the reported message, when its signature verified, it carried one and its id is at most 64 bytes long. Null otherwise."
    },
    {
      "name": "fingerprint",
      "type": [
        "null",
        {
          "type": "fixed",
          "name": "ErrorFingerprint",
          "size": 8,
          "doc": "A CRC-64-AVRO fingerprint, 8 bytes in little-endian order, as spec/envelope.md defines."
        }
      ],
      "default": null,
      "doc": "For SCHEMA_UNKNOWN, the fingerprint of the body; for FORMAT_UNSUPPORTED, the fingerprint of the envelope. Null for every other code."
    },
    {
      "name": "field",
      "type": [
        "null",
        "string"
      ],
      "default": null,
      "doc": "For VALUE_INVALID, the path of the value that breaks a rule, by the field names of the offered schema, as spec/metadata.md defines it: an empty string for the record itself. Null for every other code, and for a path above 1024 bytes."
    },
    {
      "name": "detail",
      "type": "string",
      "default": "",
      "doc": "A description for logs, in English, as plain text on one line of at most 1024 bytes. Empty when there is none. It is not shown to the user as the only explanation."
    }
  ]
}

{
  "type": "record",
  "name": "QrPayload",
  "namespace": "axt",
  "doc": "What a QR code shown by an app carries: its signing key and how to reach it on the local network and through a relay. Defined in spec/transports.md. It is not a message and is not signed; scanning it in person confirms the key. Its schema changes only with a new payload version.",
  "fields": [
    {
      "name": "signing_key",
      "type": {
        "type": "fixed",
        "name": "QrPayloadSigningKey",
        "size": 32,
        "doc": "An Ed25519 public key in the encoding of RFC 8032. Defined in spec/keys.md."
      },
      "doc": "The Ed25519 public key of the installation that shows the code, the sender of every message it sends."
    },
    {
      "name": "encryption_key",
      "type": [
        "null",
        {
          "type": "fixed",
          "name": "QrPayloadEncryptionKey",
          "size": 32,
          "doc": "An X25519 public key in the encoding of RFC 7748. Defined in spec/keys.md."
        }
      ],
      "default": null,
      "doc": "The X25519 public key with which other apps encrypt messages to the installation through a relay. Null when the code names no relay; it is present exactly when relay is."
    },
    {
      "name": "local",
      "type": [
        "null",
        {
          "type": "record",
          "name": "QrPayloadLocal",
          "doc": "Where the installation listens on the local network while it shows the code.",
          "fields": [
            {
              "name": "addresses",
              "type": {
                "type": "array",
                "items": "bytes"
              },
              "doc": "One to four IP addresses of the installation, each 4 bytes for IPv4 or 16 bytes for IPv6, in network byte order, in the order in which a scanner tries them."
            },
            {
              "name": "port",
